namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Description is required.")]
    [StringLength(500, ErrorMessage = "Description must be 500 characters or fewer.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one ingredient is required.")]
    [MinLength(1, ErrorMessage = "At least one ingredient is required.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "At least one step is required.")]
    [MinLength(1, ErrorMessage = "At least one step is required.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly over the dough.", "Tear mozzarella and distribute over the sauce.", "Bake for 10–12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 50
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, pancetta, and black pepper.",
                Ingredients = ["Spaghetti", "Pancetta (200g)", "Eggs (3)", "Pecorino Romano (100g)", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated Pecorino and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta off heat.", "Pour egg mixture over pasta and toss quickly, adding pasta water as needed."],
                TotalRatings = 8, RatingSum = 35
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast (500g)", "Yogurt", "Garam masala", "Cumin", "Tomato sauce", "Heavy cream", "Garlic", "Ginger", "Onion"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger in a pan.", "Add tomato sauce and spices; simmer 15 minutes.", "Stir in cream and add the cooked chicken.", "Simmer 10 more minutes and serve with rice."],
                TotalRatings = 15, RatingSum = 68
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "A tangy, savory stir-fried noodle dish loaded with vegetables.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Carrots", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Eggs"],
                Steps = ["Soak rice noodles in warm water for 20 minutes.", "Press and cube tofu; fry until golden.", "Scramble eggs in the same pan.", "Add noodles, tamarind paste, fish sauce, and sugar.", "Toss in vegetables and tofu.", "Serve topped with peanuts, lime, and green onions."],
                TotalRatings = 6, RatingSum = 25
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef (500g)", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = ["Brown the ground beef in a skillet.", "Add taco seasoning and water; simmer 5 minutes.", "Warm tortillas in a dry pan.", "Assemble tacos with beef and desired toppings.", "Serve with salsa and sour cream."],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh, creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados (3)", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve avocados and remove pits.", "Mash avocado in a bowl to desired consistency.", "Stir in diced onion, tomato, jalapeño, and cilantro.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 7, Title = "Miso Soup", Category = "Japanese",
                Description = "A comforting Japanese soup with tofu, seaweed, and scallions.",
                Ingredients = ["Dashi stock (4 cups)", "Miso paste (3 tbsp)", "Silken tofu", "Wakame seaweed", "Green onions"],
                Steps = ["Bring dashi stock to a simmer.", "Add wakame and tofu cubes.", "Remove from heat; dissolve miso paste into the broth.", "Garnish with sliced green onions.", "Serve immediately."],
                TotalRatings = 5, RatingSum = 22
            },
            new Recipe
            {
                Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Classic chewy cookies loaded with chocolate chips.",
                Ingredients = ["Butter (1 cup)", "Sugar (3/4 cup)", "Brown sugar (3/4 cup)", "Eggs (2)", "Vanilla extract", "Flour (2 1/4 cups)", "Baking soda", "Salt", "Chocolate chips (2 cups)"],
                Steps = ["Preheat oven to 375°F (190°C).", "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour, baking soda, and salt.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheets.", "Bake 9–11 minutes until golden edges."],
                TotalRatings = 20, RatingSum = 92
            },
        ];
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        });
    }
}

