arguments.file_text:
@using RecipeShare.Services
@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center gap-2">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= _selectedRating ? "filled" : "")"
                  role="button"
                  @onclick="() => Rate(star)"
                  title="Rate @star star@(star > 1 ? "s" : "")">
                @(star <= _selectedRating ? "★" : "☆")
            </span>
        }
    </div>
    <span class="text-muted small">
        @if (_hasRated)
        {
            <span class="text-success">Thanks! You rated @_selectedRating star@(_selectedRating > 1 ? "s" : "").</span>
        }
        else
        {
            <span>@AverageRating.ToString("0.0") avg (@TotalRatings ratings)</span>
        }
    </span>
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star.filled {
        color: #f5a623;
    }
    .star-rating .star:hover {
        color: #f5a623;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int TotalRatings { get; set; }

    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private bool _hasRated;

    private void Rate(int stars)
    {
        if (_hasRated) return;

        _selectedRating = stars;
        _hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

@page "/"
@using RecipeShare.Services

<PageTitle>RecipeShare — Home</PageTitle>

<div class="container py-4">
    <div class="text-center mb-5">
        <h1 class="display-4">🍽️ RecipeShare</h1>
        <p class="lead text-muted">Discover and share delicious recipes from around the world.</p>
    </div>

    <h2 class="mb-3">Browse by Category</h2>
    <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-4">
        @foreach (var category in Categories)
        {
            <div class="col">
                <a href="category/@category" class="text-decoration-none">
                    <div class="card h-100 shadow-sm border-0">
                        <div class="card-body text-center">
                            <h3 class="card-title">@GetEmoji(category) @category</h3>
                            <p class="card-text text-muted">Explore @category recipes</p>
                        </div>
                    </div>
                </a>
            </div>
        }
    </div>

    <div class="text-center mt-5">
        <a href="submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
    </div>
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories { get; set; } = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Japanese" => "🇯🇵",
        "Desserts" => "🍰",
        _ => "🍴"
    };
}

@page "/category/{CategoryName}"
@using RecipeShare.Models
@using RecipeShare.Services

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active" aria-current="page">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4">
            @foreach (var recipe in Recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">
                                <a href="recipe/@recipe.Id" class="text-decoration-none">@recipe.Title</a>
                            </h5>
                            <p class="card-text text-muted">@recipe.Description</p>
                            <div class="d-flex justify-content-between align-items-center">
                                <small class="text-warning">
                                    @for (int i = 0; i < (int)Math.Round(recipe.AverageRating); i++) { <span>★</span> }
                                    @for (int i = (int)Math.Round(recipe.AverageRating); i < 5; i++) { <span class="text-muted">☆</span> }
                                </small>
                                <small class="text-muted">@recipe.AverageRating.ToString("0.0") (@recipe.TotalRatings ratings)</small>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<Recipe> Recipes { get; set; } = [];

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Components.Shared
@using RecipeShare.Models
@using RecipeShare.Services

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active" aria-current="page">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1 class="mb-2">@Recipe.Title</h1>
        <p class="lead text-muted">@Recipe.Description</p>

        <div class="mb-4">
            <StarRating RecipeId="@Recipe.Id"
                        AverageRating="@Recipe.AverageRating"
                        TotalRatings="@Recipe.TotalRatings" />
        </div>

        <div class="row">
            <div class="col-md-4 mb-4">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">🥘 Ingredients</h5></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in Recipe.Ingredients)
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>

            <div class="col-md-8 mb-4">
                <div class="card">
                    <div class="card-header"><h5 class="mb-0">📋 Steps</h5></div>
                    <div class="card-body">
                        <ol class="mb-0">
                            @foreach (var step in Recipe.Steps)
                            {
                                <li class="mb-2">@step</li>
                            }
                        </ol>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@using RecipeShare.Models
@using RecipeShare.Services
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active" aria-current="page">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit a Recipe</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe submitted!</h4>
            <p>Your recipe "<strong>@_model.Title</strong>" has been added. <a href="category/@_model.Category">View it in @_model.Category</a>.</p>
            <button class="btn btn-outline-success" @onclick="Reset">Submit Another</button>
        </div>
    }
    else
    {
        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g. Grandma's Apple Pie" />
                <ValidationMessage For="() => _model.Title" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in _categories)
                    {
                        <option value="@cat">@cat</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _model.Category" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="description" class="form-label">Description</label>
                <InputTextArea id="description" class="form-control" rows="2" @bind-Value="_model.Description" placeholder="Brief description of the dish..." />
                <ValidationMessage For="() => _model.Description" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients <small class="text-muted">(one per line)</small></label>
                <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps <small class="text-muted">(one per line)</small></label>
                <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.Steps" placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Bake for 30 minutes." />
                <ValidationMessage For="() => _model.Steps" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private RecipeSubmission _model = new();
    private IReadOnlyList<string> _categories = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model);
        _submitted = true;
    }

    private void Reset()
    {
        _model = new RecipeSubmission();
        _submitted = false;
    }
}

